import type { ProjectWithTasks } from "@/types/project";
import type Task from "@/types/task";

export type BoardFilters = {
  status: string[] | null;
  priority: string[] | null;
  assignee: string[] | null;
  dueDate: string[] | null;
  labels: string[] | null;
};

export const DUE_DATE_FILTER_VALUES = {
  dueNextWeek: "dueNextWeek",
  dueThisWeek: "dueThisWeek",
  noDueDate: "noDueDate",
} as const;

const DEFAULT_FILTERS: BoardFilters = {
  status: null,
  priority: null,
  assignee: null,
  dueDate: null,
  labels: null,
};

const FILTER_KEYS: Array<keyof BoardFilters> = [
  "status",
  "priority",
  "assignee",
  "dueDate",
  "labels",
];

function normalizeFilters(raw: unknown): BoardFilters {
  if (!raw || typeof raw !== "object") {
    return DEFAULT_FILTERS;
  }

  const candidate = raw as Partial<Record<keyof BoardFilters, unknown>>;
  const normalized = { ...DEFAULT_FILTERS };

  for (const key of FILTER_KEYS) {
    const value = candidate[key];
    if (Array.isArray(value)) {
      const values = value.filter((v): v is string => typeof v === "string");
      normalized[key] = values.length > 0 ? values : null;
    }
  }

  return normalized;
}

type TaskScopedLabel = {
  name: string;
  taskId: string | null;
};

export function getTaskLabelOptions<T extends TaskScopedLabel>(
  labels: T[],
  taskId: string,
) {
  const labelMap = new Map<string, T>();

  for (const label of labels) {
    if (label.taskId !== null && label.taskId !== taskId) continue;

    const existing = labelMap.get(label.name);
    if (!existing || (label.taskId === null && existing.taskId !== null)) {
      labelMap.set(label.name, label);
    }
  }

  return Array.from(labelMap.values());
}

